head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 설정합니다.",
    "validation" : [
        "imageSrc(선택) 파라미터에 null 설정 시 Body Cell 의 imageSrc 속성값이 제거되고, Column 의 imageSrc 속성이 적용되어야 합니다.",
        "imageSrc(선택) 파라미터에 undefined 설정 시 Body Cell 의 imageSrc 속성값이 제거되고, Column 의 imageSrc 속성이 적용되어야 합니다.",
        "imageSrc(선택) 파라미터 생략 시 기본값(undefined)으로 동작하여 Body Cell 의 imageSrc 속성값이 제거되고, Column 의 imageSrc 속성이 적용되어야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_rowIndex.setSelectedIndex(0);
    par_columnInfo.setSelectedIndex(1);
    par_imageSrc.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Column 구성(인덱스) : 0 name(text) / 1 timg(textImage + Column imageSrc 설정)
//    · timg Column 에 imageSrc 를 명시 설정 → Body Cell 의 imageSrc 가 제거되었을 때
//      Column 의 imageSrc 로 복귀하는지 확인하기 위한 전제
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] timg Column(인덱스 1) 에 Column imageSrc = /cm/images/base/ico_grid_del.svg (작은 X 모양 삭제 아이콘) 를 설정했습니다.\n[절차] rowIndex / columnInfo / imageSrc(null, undefined, 생략) 를 선택하고 setCellImageSrc 버튼을 클릭하세요. 버튼은 먼저 해당 Body Cell 에 /img/gif.gif (큰 컬러 GIF) 를 설정하여 Cell 단위 imageSrc 가 적용된 상태를 만든 뒤, 선택한 값으로 다시 호출합니다.\n[확인] 결과창의 호출 전 이미지 경로(/img/gif.gif) 와 호출 후 이미지 경로(/cm/images/base/ico_grid_del.svg) 를 비교하고, 그리드의 아이콘이 GIF 에서 삭제 아이콘으로 되돌아가는지 확인하세요."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg" name="timg" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "timg": "수정" },
        { "name": "Jane", "timg": "수정" },
        { "name": "Mike", "timg": "수정" },
        { "name": "Amy",  "timg": "수정" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:480px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setCellImageSrc test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol1" value="name (0, text)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="timg (1, textImage)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="timg" dataList="timg"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Cell 에 실제 표시된 이미지 경로 확인
scwin.getCellImgSrc = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    if (!imgEl || !imgEl.getAttribute("src")) {
        return "(이미지 미표시)";
    }
    return imgEl.getAttribute("src");
}



scwin.btn_setCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());
    let imageSrcText = par_imageSrc.getText();

    // 사전 설정 : Body Cell 의 imageSrc 를 Column 의 imageSrc 와 다른 이미지로 설정
    //  → 이후 null / undefined / 생략 호출 시 Cell 값이 제거되고 Column 값으로 복귀함을 대비 확인
    target1.setCellImageSrc(rowIndex, columnInfo, "/img/gif.gif");
    wf_body_bottom.getObj("scwin").setReturnValue("호출 전 Cell 이미지 경로 : " + scwin.getCellImgSrc(rowIndex, columnInfo));

    let rtn;
    let paramDesc;
    if (imageSrcText === "") {
        // imageSrc(선택) 파라미터 생략
        rtn = target1.setCellImageSrc(rowIndex, columnInfo);
        paramDesc = "(생략)";
    } else if (imageSrcText === "null") {
        rtn = target1.setCellImageSrc(rowIndex, columnInfo, null);
        paramDesc = "null";
    } else {
        rtn = target1.setCellImageSrc(rowIndex, columnInfo, undefined);
        paramDesc = "undefined";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setCellImageSrc(" + rowIndex + ", " + columnInfo + ", " + paramDesc + ") : " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + target1.getCellImageSrc(rowIndex, columnInfo));
    wf_body_bottom.getObj("scwin").setReturnValue("호출 후 Cell 이미지 경로 : " + scwin.getCellImgSrc(rowIndex, columnInfo));
}
